private val Blue=Color(0xFF0756A4); private val Cyan=Color(0xFF13A7D8); private val Navy=Color(0xFF102B4E); private val Page=Color(0xFFF1F7FC)
private fun today()=SimpleDateFormat("yyyy-MM-dd",Locale.US).format(Date())
class MainActivity:ComponentActivity(){
 private val db by lazy{FactoryDatabase.get(this)}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);lifecycleScope.launch{if(db.factoryDao().activeProducts().isEmpty()) listOf(ProductEntity(name="300ml",sizeLabel="300ml",bottlesPerPack=300),ProductEntity(name="500ml",sizeLabel="500ml",bottlesPerPack=200),ProductEntity(name="1 Ltr",sizeLabel="1 litre",bottlesPerPack=120),ProductEntity(name="200ml Green",sizeLabel="200ml",colour="Green",bottlesPerPack=300),ProductEntity(name="200ml Milk White",sizeLabel="200ml",colour="Milk White",bottlesPerPack=300),ProductEntity(name="200ml Clear",sizeLabel="200ml",bottlesPerPack=300)).forEach{runCatching{db.factoryDao().insertProduct(it)}}};setContent{FactoryApp(db.factoryDao())}}
}
private enum class PageTab{HOME,PRODUCTS,PRODUCTION,PACKING,STOCK,DISPATCH,ELECTRICITY,REPORTS}
@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun FactoryApp(dao:FactoryDao){
 var tab by remember{mutableStateOf(PageTab.HOME)}; var dialog by remember{mutableStateOf("")}; var message by remember{mutableStateOf<String?>(null)}; val scope=rememberCoroutineScope()
 val products by dao.observeProducts().collectAsStateWithLifecycle(emptyList()); val production by dao.observeProduction().collectAsStateWithLifecycle(emptyList()); val packing by dao.observePacking().collectAsStateWithLifecycle(emptyList()); val dispatches by dao.observeDispatches().collectAsStateWithLifecycle(emptyList()); val meters by dao.observeMeterReadings().collectAsStateWithLifecycle(emptyList()); val active=products.filter{it.active}; val date=today()
 MaterialTheme(colorScheme=lightColorScheme(primary=Blue,secondary=Cyan,background=Page,surface=Color.White)){
 Scaffold(topBar={TopAppBar(title={Column{Text("TCK FactoryFlow",fontWeight=FontWeight.Bold,color=Navy);Text("Bottle Manufacturing Management",fontSize=11.sp,color=Blue)}},actions={Text("♛",Modifier.padding(16.dp),color=Color(0xFFD6A329),fontWeight=FontWeight.Black)},colors=TopAppBarDefaults.topAppBarColors(containerColor=Color.White))},bottomBar={NavigationBar(containerColor=Color.White){listOf(PageTab.HOME,PageTab.PRODUCTION,PageTab.STOCK,PageTab.REPORTS,PageTab.PRODUCTS).forEach{t->NavigationBarItem(selected=tab==t,onClick={tab=t},icon={Icon(when(t){PageTab.HOME->Icons.Default.Home;PageTab.PRODUCTION->Icons.Default.Build;PageTab.STOCK->Icons.Default.Inventory2;PageTab.REPORTS->Icons.Default.BarChart;else->Icons.Default.WaterDrop},null)},label={Text(t.name.lowercase().replaceFirstChar{it.uppercase()},fontSize=9.sp)})}}},containerColor=Page){padding->
 Box(Modifier.fillMaxSize().padding(padding)){
 when(tab){
 PageTab.HOME->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){
 item{Text("Factory dashboard",fontSize=25.sp,fontWeight=FontWeight.Bold,color=Navy);Text(date,color=Blue)}
 item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Bottles produced",production.filter{it.productionDate==date}.sumOf{it.producedBottles}.toString(),Modifier.weight(1f));Metric("Rejected bottles",production.filter{it.productionDate==date}.sumOf{it.rejectedBottles}.toString(),Modifier.weight(1f))}}
 item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Packs completed",packing.filter{it.packingDate==date}.sumOf{it.completePacks}.toString(),Modifier.weight(1f));Metric("Packs dispatched",dispatches.filter{it.dispatchDate==date}.sumOf{it.packsDispatched}.toString(),Modifier.weight(1f))}}
 item{Metric("Electricity today",meters.filter{it.readingDate==date}.sumOf{it.consumption}.toString()+" units",Modifier.fillMaxWidth())}
 item{Text("Quick actions",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)}
 item{Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Production",Icons.Default.Build,{dialog="production"},Modifier.weight(1f));Action("Packing",Icons.Default.Inventory2,{dialog="packing"},Modifier.weight(1f));Action("Dispatch",Icons.Default.LocalShipping,{dialog="dispatch"},Modifier.weight(1f))};Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Products",Icons.Default.WaterDrop,{tab=PageTab.PRODUCTS},Modifier.weight(1f));Action("Electricity",Icons.Default.Bolt,{dialog="meter"},Modifier.weight(1f));Action("Reports",Icons.Default.BarChart,{tab=PageTab.REPORTS},Modifier.weight(1f))}}}
 item{Text("Product pack settings",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)};items(active){p->Record(p.name,p.bottlesPerPack.toString()+" bottles per pack",p.colour)}
 item{Text("Recent production",fontSize=18.sp,fontWeight=FontWeight.Bold,color=Navy)};items(production.take(8)){e->Record(e.productNameSnapshot,e.goodBottles.toString()+" good · "+e.rejectedBottles+" rejected",e.productionDate)}
 }
 PageTab.PRODUCTS->Column(Modifier.fillMaxSize().padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("Product Master",Modifier.weight(1f),fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy);Button(onClick={dialog="product"}){Text("+ Add")}};LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(products){p->Record(p.name,p.sizeLabel+" · "+p.bottlesPerPack+" bottles/pack",if(p.active)"Active" else "Archived");if(p.active)TextButton(onClick={scope.launch{dao.updateProduct(p.id,p.name,p.sizeLabel,p.colour,p.bottlesPerPack,false)}}){Text("Deactivate")}}}}
 PageTab.PRODUCTION->ListScreen("Production",production.map{Triple(it.productNameSnapshot,"Produced "+it.producedBottles+" · Good "+it.goodBottles+" · Reject "+it.rejectedBottles,it.productionDate)}, {dialog="production"})
 PageTab.PACKING->ListScreen("Packing / Finishing",packing.map{Triple(it.productNameSnapshot,it.completePacks.toString()+" packs · "+it.looseBottles+" loose bottles",it.packingDate)}, {dialog="packing"})
 PageTab.DISPATCH->ListScreen("Delivery / Dispatch",dispatches.map{Triple(it.customerName,it.productNameSnapshot+" · "+it.packsDispatched+" packs",it.dispatchDate+" · "+it.dispatchReference)}, {dialog="dispatch"})
 PageTab.ELECTRICITY->ListScreen("Electricity",meters.map{Triple(it.meterId,it.consumption.toString()+" units",it.readingDate)}, {dialog="meter"})
 PageTab.STOCK->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("Finished Stock",fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy)};items(active){p->val packsMade=packing.filter{it.productId==p.id}.sumOf{it.completePacks};val sent=dispatches.filter{it.productId==p.id}.sumOf{it.packsDispatched};Record(p.name,"Available packs: "+(packsMade-sent).coerceAtLeast(0),"Packed "+packsMade+" · Dispatched "+sent)}}
 PageTab.REPORTS->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Reports & Analytics",fontSize=23.sp,fontWeight=FontWeight.Bold,color=Navy)};item{Metric("Good bottles",production.sumOf{it.goodBottles}.toString(),Modifier.fillMaxWidth())};item{Metric("Complete packs",packing.sumOf{it.completePacks}.toString(),Modifier.fillMaxWidth())};item{Metric("Dispatched packs",dispatches.sumOf{it.packsDispatched}.toString(),Modifier.fillMaxWidth())};item{Metric("Electricity",meters.sumOf{it.consumption}.toString()+" units",Modifier.fillMaxWidth())}}
 }
 message?.let{Text(it,Modifier.align(Alignment.BottomCenter).padding(12.dp).background(Color.White,RoundedCornerShape(12.dp)).padding(12.dp),color=Blue)}
 }
 }
 }
 if(dialog=="product")ProductForm({dialog=""}){n,s,c,p->scope.launch{runCatching{dao.insertProduct(ProductEntity(name=n,sizeLabel=s,colour=c,bottlesPerPack=p))}.onSuccess{message="Product saved"}.onFailure{message=it.message}};dialog=""}
 if(dialog=="production")ProductionForm(active,{dialog=""}){p,d,total,good,rejected,machine,remarks->scope.launch{runCatching{ProductionQuantities(total,good,rejected).validate();require(p!=null){"Choose a product"};dao.insertProduction(ProductionEntryEntity(productId=p.id,productNameSnapshot=p.name,productionDate=d,producedBottles=total,goodBottles=good,rejectedBottles=rejected,machineName=machine,remarks=remarks))}.onSuccess{message="Production saved"}.onFailure{message=it.message}};dialog=""}
 if(dialog=="packing")PackingForm(active,dao,{dialog=""}){p,d,n->scope.launch{runCatching{require(p!=null){"Choose a product"};val available=dao.totalGoodBottles(p.id)-dao.totalPackedBottles(p.id);require(n>0&&n<=available){"Available unpacked bottles: "+available.coerceAtLeast(0)};val calc=PackCalculation.calculate(n,p.bottlesPerPack);dao.insertPacking(PackingEntryEntity(productId=p.id,productNameSnapshot=p.name,packingDate=d,bottlesConsumed=n,completePacks=calc.completePacks,looseBottles=calc.looseBottles));"Saved "+calc.completePacks+" packs and "+calc.looseBottles+" loose bottles"}.onSuccess{message=it}.onFailure{message=it.message}};dialog=""}
 if(dialog=="dispatch")DispatchForm(active,dao,{dialog=""}){p,d,customer,n,ref,remarks->scope.launch{runCatching{require(p!=null){"Choose a product"};DispatchRules.remainingStock(dao.totalCompletePacks(p.id)-dao.totalDispatchedPacks(p.id),n);dao.insertDispatch(DispatchEntryEntity(dispatchReference=ref.ifBlank{"DSP-"+System.currentTimeMillis()},dispatchDate=d,customerName=customer,productId=p.id,productNameSnapshot=p.name,packsDispatched=n,remarks=remarks));"Dispatch saved"}.onSuccess{message=it}.onFailure{message=it.message}};dialog=""}
 if(dialog=="meter")MeterForm({dialog=""}){d,m,s,e,r->scope.launch{runCatching{val used=ElectricityRules.consumption(s,e);dao.insertMeterReading(MeterReadingEntity(meterId=m,readingDate=d,startReading=s,endReading=e,consumption=used,remarks=r));"Reading saved: "+used+" units"}.onSuccess{message=it}.onFailure{message=it.message}};dialog=""}
}
@Composable private fun Metric(title:String,value:String,modifier:Modifier=Modifier){Surface(modifier,color=Color.White,shape=RoundedCornerShape(16.dp),shadowElevation=1.dp){Column(Modifier.padding(15.dp)){Text(title,color=Blue,fontSize=12.sp);Text(value,color=Navy,fontWeight=FontWeight.Bold,fontSize=23.sp)}}}
@Composable private fun Action(title:String,icon:androidx.compose.ui.graphics.vector.ImageVector,click:()->Unit,modifier:Modifier=Modifier){Surface(onClick=click,modifier=modifier,color=Color.White,shape=RoundedCornerShape(14.dp),shadowElevation=1.dp){Column(Modifier.fillMaxWidth().padding(13.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(icon,null,tint=Blue);Text(title,fontSize=11.sp,color=Navy)}}}
@Composable private fun Record(title:String,detail:String,sub:String){Surface(color=Color.White,shape=RoundedCornerShape(12.dp)){Row(Modifier.fillMaxWidth().padding(13.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.WaterDrop,null,tint=Cyan);Column(Modifier.weight(1f).padding(start=10.dp)){Text(title,fontWeight=FontWeight.Bold,color=Navy);Text(detail,fontSize=12.sp,color=Blue);Text(sub,fontSize=10.sp,color=Color.Gray)}}}}
@Composable private fun ListScreen(title:String,rows:List<Triple<String,String,String>>,add:()->Unit){Column(Modifier.fillMaxSize().padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(title,Modifier.weight(1f),fontSize=21.sp,fontWeight=FontWeight.Bold,color=Navy);Button(onClick=add){Text("+ Add")}};Spacer(Modifier.height(10.dp));LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){items(rows){Record(it.first,it.second,it.third)}}}}
@Composable private fun Field(label:String,value:String,onChange:(String)->Unit,decimal:Boolean=false){OutlinedTextField(value,onChange,label={Text(label)},singleLine=true,keyboardOptions=KeyboardOptions(keyboardType=if(decimal)KeyboardType.Decimal else KeyboardType.Number),modifier=Modifier.fillMaxWidth())}
@Composable private fun DateField(value:String,onChange:(String)->Unit){OutlinedTextField(value,onChange,label={Text("Date (yyyy-MM-dd)")},singleLine=true,modifier=Modifier.fillMaxWidth())}
@Composable private fun ProductPicker(products:List<ProductEntity>,selected:ProductEntity?,onSelect:(ProductEntity?)->Unit){var expanded by remember{mutableStateOf(false)};Box{OutlinedButton(onClick={expanded=true},modifier=Modifier.fillMaxWidth()){Text(selected?.name?:"Select product")};DropdownMenu(expanded=expanded,onDismissRequest={expanded=false}){products.forEach{p->DropdownMenuItem(text={Text(p.name)},onClick={onSelect(p).let{expanded=false}})}}}}
@Composable private fun ProductForm(close:()->Unit,save:(String,String,String,Int)->Unit){var name by remember{mutableStateOf("")};var size by remember{mutableStateOf("")};var colour by remember{mutableStateOf("Clear")};var pack by remember{mutableStateOf("300")};AlertDialog(onDismissRequest=close,title={Text("Add product")},text={Column(verticalArrangement=Arrangement.spacedBy(6.dp)){OutlinedTextField(name,{name=it},label={Text("Product name")});OutlinedTextField(size,{size=it},label={Text("Size / type")});OutlinedTextField(colour,{colour=it},label={Text("Colour")});Field("Bottles per pack",pack,{pack=it.filter(Char::isDigit)})}},confirmButton={Button(enabled=name.isNotBlank()&&size.isNotBlank()&&(pack.toIntOrNull()?:0)>0,onClick={save(name.trim(),size.trim(),colour.trim(),pack.toInt())}){Text("Save")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}
@Composable private fun ProductionForm(products:List<ProductEntity>,close:()->Unit,save:(ProductEntity?,String,Int,Int,Int,String,String)->Unit){var p by remember{mutableStateOf(products.firstOrNull())};var d by remember{mutableStateOf(today())};var total by remember{mutableStateOf("")};var good by remember{mutableStateOf("")};var rejected by remember{mutableStateOf("0")};var machine by remember{mutableStateOf("Machine 1")};var remarks by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Production entry")},text={Column(verticalArrangement=Arrangement.spacedBy(5.dp)){ProductPicker(products,p){p=it};DateField(d){d=it};Field("Produced bottles",total){total=it};Field("Good bottles",good){good=it};Field("Rejected bottles",rejected){rejected=it};OutlinedTextField(machine,{machine=it},label={Text("Machine")});OutlinedTextField(remarks,{remarks=it},label={Text("Remarks")})}},confirmButton={Button(enabled=(total.toIntOrNull()?:-1)>=0&&(good.toIntOrNull()?:-1)>=0&&(rejected.toIntOrNull()?:-1)>=0,onClick={val a=total.toIntOrNull();val b=good.toIntOrNull();val c=rejected.toIntOrNull();if(a!=null&&b!=null&&c!=null)save(p,d,a,b,c,machine,remarks)}){Text("Save")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}
@Composable private fun PackingForm(products:List<ProductEntity>,dao:FactoryDao,close:()->Unit,save:(ProductEntity?,String,Int)->Unit){var p by remember{mutableStateOf(products.firstOrNull())};var d by remember{mutableStateOf(today())};var bottles by remember{mutableStateOf("")};var available by remember{mutableIntStateOf(0)};LaunchedEffect(p?.id){p?.let{available=dao.totalGoodBottles(it.id)-dao.totalPackedBottles(it.id)}};val n=bottles.toIntOrNull()?:0;val calc=runCatching{PackCalculation.calculate(n,p?.bottlesPerPack?:0)}.getOrNull();AlertDialog(onDismissRequest=close,title={Text("Packing / finishing")},text={Column(verticalArrangement=Arrangement.spacedBy(6.dp)){ProductPicker(products,p){p=it};DateField(d){d=it};Text("Available unpacked bottles: "+available.coerceAtLeast(0),color=Blue);Field("Bottles to pack",bottles){bottles=it};calc?.let{Text("Auto: "+it.completePacks+" packs + "+it.looseBottles+" loose",color=Blue)}}},confirmButton={Button(enabled=n>0&&n<=available&&p!=null,onClick={save(p,d,n)}){Text("Save packing")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}
@Composable private fun DispatchForm(products:List<ProductEntity>,dao:FactoryDao,close:()->Unit,save:(ProductEntity?,String,String,Int,String,String)->Unit){var p by remember{mutableStateOf(products.firstOrNull())};var d by remember{mutableStateOf(today())};var customer by remember{mutableStateOf("Nachiyar Cooldrinks")};var packs by remember{mutableStateOf("")};var ref by remember{mutableStateOf("")};var remarks by remember{mutableStateOf("")};var stock by remember{mutableIntStateOf(0)};LaunchedEffect(p?.id){p?.let{stock=dao.totalCompletePacks(it.id)-dao.totalDispatchedPacks(it.id)}};val n=packs.toIntOrNull()?:0;AlertDialog(onDismissRequest=close,title={Text("Delivery / dispatch")},text={Column(verticalArrangement=Arrangement.spacedBy(6.dp)){DateField(d){d=it};OutlinedTextField(customer,{customer=it},label={Text("Customer")});ProductPicker(products,p){p=it};Text("Available finished packs: "+stock.coerceAtLeast(0),color=Blue);Field("Packs to dispatch",packs){packs=it};OutlinedTextField(ref,{ref=it},label={Text("Delivery reference")});OutlinedTextField(remarks,{remarks=it},label={Text("Remarks")})}},confirmButton={Button(enabled=n>0&&n<=stock&&p!=null&&customer.isNotBlank(),onClick={save(p,d,customer,n,ref,remarks)}){Text("Confirm dispatch")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}
@Composable private fun MeterForm(close:()->Unit,save:(String,String,Double,Double,String)->Unit){var d by remember{mutableStateOf(today())};var meter by remember{mutableStateOf("MAIN")};var start by remember{mutableStateOf("")};var end by remember{mutableStateOf("")};var remarks by remember{mutableStateOf("")};val used=runCatching{ElectricityRules.consumption(start.toDouble(),end.toDouble())}.getOrNull();AlertDialog(onDismissRequest=close,title={Text("Electricity reading")},text={Column(verticalArrangement=Arrangement.spacedBy(6.dp)){DateField(d){d=it};OutlinedTextField(meter,{meter=it},label={Text("Meter ID")});Field("Start reading",start,{start=it},true);Field("End reading",end,{end=it},true);Text("Consumption: "+(used?.toString()?: "—")+" units",color=Blue);OutlinedTextField(remarks,{remarks=it},label={Text("Remarks")})}},confirmButton={Button(enabled=used!=null,onClick={if(used!=null)save(d,meter,start.toDouble(),end.toDouble(),remarks)}){Text("Save reading")}},dismissButton={TextButton(onClick=close){Text("Cancel")}})}